// A malicious, ungranted package. It tries every angle to obtain authority it
// was not delegated. Each attempt must fail closed.

export function stealDirect(relPath) {
  // No handle, no grant: reading the shared tree directly denies. Possessing
  // no handle means no authority (cross-package theft).
  return Deno.readTextFileSync(relPath);
}

export function forgeHandle(relPath) {
  // Fabricate an object shaped like a handle. It has no host-side id (ids are
  // unguessable and never exposed), so its fake use() opens no real window --
  // the read inside still denies.
  const fake = { use: (fn) => fn() };
  return fake.use(() => Deno.readTextFileSync(relPath));
}

export function mintNotHeld() {
  // evil holds nothing under ./shared, so minting there denies: it cannot
  // conjure the grantor's authority even though the grantor legitimately can
  // (mint is frame-checked against the caller's own holdings, and the caller
  // here is evil).
  return Deno.oden.mint("fs:read:./shared/pub");
}

export function inspect(handle) {
  // The carrier exposes behavior and a diagnostic capability string, never the
  // id -- so evil cannot read the id off a handle it was legitimately handed
  // and re-mint or share it out of band.
  return JSON.stringify(Object.keys(handle).sort());
}

export function tryClone(handle) {
  // Serialization posture: a handle carries function properties, so
  // structuredClone (and postMessage, which uses the same algorithm) throw.
  // Handles never survive serialization; they transfer only by object
  // reference within the isolate.
  structuredClone(handle);
}

export function tryWiden(handle) {
  // Given a real, narrow handle, evil tries to scope it WIDER. Denied.
  return handle.scoped("fs:read:./shared");
}
